CREATE TABLE suppliers(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,contact VARCHAR(150),active BOOLEAN DEFAULT TRUE);
CREATE TABLE purchase_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,supplier_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'ORDERED',created_by VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE purchase_order_lines(id BIGINT PRIMARY KEY AUTO_INCREMENT,purchase_order_id BIGINT NOT NULL,inventory_item_id BIGINT NOT NULL,quantity DECIMAL(12,2) NOT NULL,received DECIMAL(12,2) NOT NULL DEFAULT 0,unit_cost DECIMAL(12,2) NOT NULL,FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id),FOREIGN KEY(inventory_item_id) REFERENCES inventory_items(id));
CREATE TABLE inventory_batches(id BIGINT PRIMARY KEY AUTO_INCREMENT,inventory_item_id BIGINT NOT NULL,batch_no VARCHAR(80) NOT NULL,expires_on DATE NOT NULL,quantity DECIMAL(12,2) NOT NULL,unit_cost DECIMAL(12,2) NOT NULL,sale_price DECIMAL(12,2) NOT NULL,UNIQUE KEY uk_item_batch(inventory_item_id,batch_no),FOREIGN KEY(inventory_item_id) REFERENCES inventory_items(id));
INSERT INTO inventory_batches(inventory_item_id,batch_no,expires_on,quantity,unit_cost,sale_price) SELECT id,COALESCE(batch_no,'INITIAL'),COALESCE(expires_on,DATE_ADD(CURDATE(),INTERVAL 1 YEAR)),stock_qty,0,0 FROM inventory_items WHERE stock_qty>0;
CREATE TABLE batch_movements(id BIGINT PRIMARY KEY AUTO_INCREMENT,batch_id BIGINT NOT NULL,quantity DECIMAL(12,2) NOT NULL,reason VARCHAR(30) NOT NULL,reference_id BIGINT,patient_id BIGINT,ward VARCHAR(80),performed_by VARCHAR(80) NOT NULL,notes VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(batch_id) REFERENCES inventory_batches(id));
CREATE TABLE pharmacy_dispenses(id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,prescription_id BIGINT,medication_order_id BIGINT,inventory_item_id BIGINT NOT NULL,quantity DECIMAL(12,2) NOT NULL,returned DECIMAL(12,2) NOT NULL DEFAULT 0,charge_amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'DISPENSED',performed_by VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE dispense_allocations(id BIGINT PRIMARY KEY AUTO_INCREMENT,dispense_id BIGINT NOT NULL,batch_id BIGINT NOT NULL,quantity DECIMAL(12,2) NOT NULL,returned DECIMAL(12,2) NOT NULL DEFAULT 0,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(dispense_id) REFERENCES pharmacy_dispenses(id),FOREIGN KEY(batch_id) REFERENCES inventory_batches(id));
CREATE TABLE ward_stock(batch_id BIGINT NOT NULL,ward VARCHAR(80) NOT NULL,quantity DECIMAL(12,2) NOT NULL,PRIMARY KEY(batch_id,ward),FOREIGN KEY(batch_id) REFERENCES inventory_batches(id));
CREATE TABLE medication_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,admission_id BIGINT NOT NULL,patient_id BIGINT NOT NULL,inventory_item_id BIGINT NOT NULL,medicine_name VARCHAR(150) NOT NULL,dose VARCHAR(80) NOT NULL,route VARCHAR(40) NOT NULL,starts_at DATETIME NOT NULL,interval_hours INT NOT NULL,dose_count INT NOT NULL,quantity_per_dose DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'ORDERED',ordered_by VARCHAR(80) NOT NULL,verified_by VARCHAR(80),verified_at DATETIME,FOREIGN KEY(admission_id) REFERENCES admissions(id));
ALTER TABLE medication_administrations ADD medication_order_id BIGINT,ADD FOREIGN KEY(medication_order_id) REFERENCES medication_orders(id);
CREATE TABLE nursing_notes(id BIGINT PRIMARY KEY AUTO_INCREMENT,admission_id BIGINT NOT NULL,note_type VARCHAR(30) NOT NULL,assessment TEXT NOT NULL,plan TEXT,nurse VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admission_id) REFERENCES admissions(id));
CREATE TABLE admission_recommendations(id BIGINT PRIMARY KEY AUTO_INCREMENT,encounter_id BIGINT NOT NULL,patient_id BIGINT NOT NULL,ward_type VARCHAR(40) NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',recommended_by VARCHAR(80) NOT NULL,admission_id BIGINT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(encounter_id) REFERENCES encounters(id));
ALTER TABLE invoice_items ADD charge_key VARCHAR(120) UNIQUE;
ALTER TABLE invoices ADD gross_total DECIMAL(12,2) NOT NULL DEFAULT 0,ADD discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0,ADD tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0;
UPDATE invoices SET gross_total=total;
CREATE TABLE invoice_adjustments(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT NOT NULL,adjustment_type VARCHAR(30) NOT NULL,amount DECIMAL(12,2) NOT NULL,reason VARCHAR(500) NOT NULL,performed_by VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE refunds(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(30) NOT NULL,reference_no VARCHAR(120) NOT NULL,reason VARCHAR(500) NOT NULL,performed_by VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
ALTER TABLE payments ADD verified_by VARCHAR(80),ADD verified_at DATETIME;
ALTER TABLE lab_order_items ADD invoice_id BIGINT,ADD sample_barcode VARCHAR(60),ADD result_notes TEXT;
ALTER TABLE lab_test_catalog ADD result_unit VARCHAR(50),ADD reference_range VARCHAR(100);
CREATE TABLE insurance_lines(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(12,2) NOT NULL,eligible_amount DECIMAL(12,2) NOT NULL,FOREIGN KEY(claim_id) REFERENCES insurance_claims(id));
CREATE TABLE insurance_settlements(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,reference_no VARCHAR(120) NOT NULL UNIQUE,received_on DATE NOT NULL,performed_by VARCHAR(80) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(claim_id) REFERENCES insurance_claims(id));
CREATE TABLE insurance_enhancements(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL,requested_amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',decision_amount DECIMAL(12,2),notes VARCHAR(500),requested_by VARCHAR(80),reviewed_by VARCHAR(80),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(claim_id) REFERENCES insurance_claims(id));
